SELECT nextval('TRIALS.SEQ_PERSONAS_ID'), 0, 'Miguel', 'Proyectista', '', '', 1, 'proyectista@proyectista.dev', '', '', '1992-10-10', EC.PN_ID, '', E.PN_ID, 0, '8b0db7e3-7cc0-4246-bed1-02d6ff3c5dd3', 8, 1
